"""#5324: a read-only roster probe must not release the two-generals wait.

ch3 2026-11-24: 24 generals country-wide with four located, every owned castle
keeping exactly one. The stuck-army fallback planned a read-only roster probe
every few minutes; each probe cleared ``defense_wait`` with "2人目の将軍が使える
ようになった" although opening a list cannot add a general, so the wait never
aged and months passed with zero sorties. The home castle was never probed at
all because its measured legs all lead to castles we already own.

Synthetic memory only.
"""
import pytest

from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun import hanjuku_chart_adjust as chart_adjust
from docich.hanjuku_speedrun.hanjuku.strategy import replan

CHAPTER = 3
HOME = chart.home_castle(CHAPTER)
OWNED = [HOME, 'グリン', 'コラダイン', 'パタゴーヌ', 'メガパタ']
ENEMIES = [c for c in chart.castles(CHAPTER)
           if not chart.is_boss_castle(c) and c not in OWNED]


def starved_memory(month='5-4', tick=1000):
    return {
        'chapter': CHAPTER, 'month': month, 'tick': tick,
        'captured': OWNED[1:],
        'home_lost': False,
        'country_general_count': {'count': 24},
        'world': {
            'sorties': {},
            'garrison': {
                HOME: [],
                'グリン': ['アルファルファ'],
                'コラダイン': ['ヘスティア'],
                'パタゴーヌ': ['ゼウス'],
                'メガパタ': ['ジェラート'],
            },
            'garrison_tick': {HOME: 100, 'グリン': 999, 'コラダイン': 999,
                              'メガパタ': 999},
        },
        'orders': {},
        '_records': [],
    }


def probe(general='—', source=HOME, target='アバロン'):
    return {'general': general, 'source': source, 'target': target,
            'cards': [], 'after': None, 'purpose': 'attack',
            'source_probe': True, 'roster_probe': True,
            'note': f'暫定: 膠着のため{source}の将軍一覧を読んでから{target}へ出撃する'}


def kinds(mem):
    return [r['decision'] for r in mem['_records']]


def test_probe_only_candidate_keeps_the_wait(monkeypatch):
    mem = starved_memory()
    monkeypatch.setattr(replan, 'interim_candidates',
                        lambda m, allow_sole=False: {'probe_stuck_1': probe()})

    assert replan._defense_gate(mem) is None
    assert mem['defense_wait'] == {'since': '5-4', 'eval_month': '5-4', 'cycles': 0}
    assert kinds(mem) == ['chart_defense_wait']


def test_probe_only_candidate_still_ages_the_wait_by_month(monkeypatch):
    mem = starved_memory()
    monkeypatch.setattr(replan, 'interim_candidates',
                        lambda m, allow_sole=False: {'probe_stuck_1': probe()})
    replan._defense_gate(mem)
    mem['month'] = '5-5'

    assert replan._defense_gate(mem) is None
    assert mem['defense_wait']['cycles'] == 1
    assert 'chart_defense_wait_released' not in kinds(mem)


def test_real_candidate_releases_the_wait(monkeypatch):
    mem = starved_memory()
    mem['defense_wait'] = {'since': '5-3', 'eval_month': '5-4', 'cycles': 1}
    move = {'general': 'ゼウス', 'source': 'パタゴーヌ', 'target': HOME,
            'purpose': 'move'}
    monkeypatch.setattr(replan, 'interim_candidates',
                        lambda m, allow_sole=False: {'move_1': move})

    assert replan._defense_gate(mem) is None
    assert 'defense_wait' not in mem
    assert kinds(mem)[-1] == 'chart_defense_wait_released'


def test_stuck_probe_reads_a_castle_with_no_attack_leg():
    # Home (and パタゴーヌ) have measured legs only to castles we already own,
    # so requiring a reachable enemy silently excluded the castles that can
    # hold the recruits.
    from docich.hanjuku_speedrun.hanjuku.strategy import routes
    mem = starved_memory()

    candidates = replan.interim_candidates(mem, allow_sole=False)

    assert list(candidates) == ['probe_stuck_1']
    stuck = candidates['probe_stuck_1']
    assert stuck['source_probe'] is True and stuck['roster_probe'] is True
    assert stuck['target'] in ENEMIES
    assert stuck['general'] == chart_adjust.PROBE_GENERAL
    assert not [e for e in ENEMIES if routes.allowed(mem, stuck['source'], e)]


def test_stuck_probe_prefers_the_stalest_no_leg_castle():
    mem = starved_memory()
    mem['world']['garrison_tick']['パタゴーヌ'] = 999
    mem['world']['garrison_tick'][HOME] = 100

    candidates = replan.interim_candidates(mem, allow_sole=False)

    assert candidates['probe_stuck_1']['source'] == HOME


def test_recently_read_castles_are_not_probed_again():
    mem = starved_memory()
    mem['world']['garrison_tick']['パタゴーヌ'] = 990
    mem['world']['garrison_tick'][HOME] = 990     # every list read 10 ticks ago

    assert replan.interim_candidates(mem, allow_sole=False) == {}
